package app.books.reader;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.widget.*;import android.view.View;import org.json.*;import java.util.*;
public class BooksWidget extends AppWidgetProvider {
 static JSONArray books(Context c){try{return new JSONArray(c.getSharedPreferences("books",0).getString("widget","[]"));}catch(Exception e){return new JSONArray();}}
 private static Bitmap cover(Context c,JSONObject book,int index){
  try{String encoded=book.optString("cover");int comma=encoded.indexOf(',');if(comma>0&&encoded.substring(0,comma).contains("base64")){byte[] bytes=android.util.Base64.decode(encoded.substring(comma+1),2);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>216||options.outHeight/options.inSampleSize>312)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap source=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(source!=null){Bitmap scaled=Bitmap.createScaledBitmap(source,108,156,true);if(scaled!=source)source.recycle();return scaled;}}}catch(Exception ignored){}
  Bitmap result=Bitmap.createBitmap(108,156,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);int[] colors={0xff315d50,0xff785449,0xff394d67,0xff6b7151};canvas.drawColor(colors[index%colors.length]);paint.setColor(0xffefe5c9);paint.setStyle(Paint.Style.STROKE);canvas.drawRect(6,6,102,150,paint);paint.setStyle(Paint.Style.FILL);paint.setTypeface(Typeface.create("serif",Typeface.BOLD));paint.setTextSize(12);String title=book.optString("title","Books");int y=38;String line="";for(String word:title.split(" ")){if(paint.measureText(line+" "+word)>86&&!line.isEmpty()){canvas.drawText(line,11,y,paint);line=word;y+=17;if(y>124)break;}else line+=(line.isEmpty()?"":" ")+word;}if(y<=141)canvas.drawText(line,11,y,paint);return result;
 }
 @Override public void onUpdate(Context c,AppWidgetManager manager,int[] ids){for(int id:ids)try{
  String group=c.getSharedPreferences("books",0).getString("widget-group-"+id,"recent");ArrayList<JSONObject> list=new ArrayList<>();JSONArray data=books(c);for(int i=0;i<data.length();i++){JSONObject b=data.getJSONObject(i);if(group.equals("favorites")&&!b.optBoolean("favorite"))continue;if(group.startsWith("tag:")){boolean matches=false;JSONArray tags=b.optJSONArray("tags");if(tags!=null)for(int t=0;t<tags.length();t++)if(tags.optString(t).equals(group.substring(4)))matches=true;if(!matches)continue;}list.add(b);}if(group.equals("recent"))list.sort((a,b)->Long.compare(b.optLong("lastRead",b.optLong("added")),a.optLong("lastRead",a.optLong("added"))));
  RemoteViews view=new RemoteViews(c.getPackageName(),R.layout.books_widget);view.setTextViewText(R.id.widget_title,"Books · "+(group.equals("favorites")?"Favorites":group.startsWith("tag:")?group.substring(4):"Library"));
  view.setOnClickPendingIntent(R.id.widget_title,PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));view.setOnClickPendingIntent(R.id.widget_settings,PendingIntent.getActivity(c,10000+id,new Intent(c,WidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
  int[] labels={R.id.book1,R.id.book2,R.id.book3},covers={R.id.cover1,R.id.cover2,R.id.cover3};ArrayList<Bitmap> bitmaps=new ArrayList<>();
  for(int i=0;i<3;i++){if(i<list.size()){JSONObject b=list.get(i);Bitmap bitmap=cover(c,b,i);bitmaps.add(bitmap);view.setImageViewBitmap(covers[i],bitmap);view.setViewVisibility(covers[i],View.VISIBLE);view.setTextViewText(labels[i],b.optString("title")+" · "+b.optInt("percent")+"%");PendingIntent open=PendingIntent.getActivity(c,(id*10)+i+1,new Intent(c,MainActivity.class).putExtra("book",b.optString("id")).setAction("book:"+b.optString("id")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);view.setOnClickPendingIntent(covers[i],open);view.setOnClickPendingIntent(labels[i],open);}else{view.setViewVisibility(covers[i],View.INVISIBLE);view.setTextViewText(labels[i],i==0?"No books in this group":"");}}
  manager.updateAppWidget(id,view);for(Bitmap bitmap:bitmaps)bitmap.recycle();
 }catch(Exception ignored){}}
 @Override public void onDeleted(Context c,int[] ids){android.content.SharedPreferences.Editor edit=c.getSharedPreferences("books",0).edit();for(int id:ids)edit.remove("widget-group-"+id);edit.apply();}
 public static void refresh(Context c){AppWidgetManager manager=AppWidgetManager.getInstance(c);new BooksWidget().onUpdate(c,manager,manager.getAppWidgetIds(new ComponentName(c,BooksWidget.class)));}
}
